package org.opensourcepingpong.competition;

import jakarta.validation.Valid;
import java.sql.Timestamp;
import java.time.Instant;
import java.util.*;
import org.opensourcepingpong.auth.AuthPrincipal;
import org.opensourcepingpong.common.api.*;
import org.opensourcepingpong.competition.algorithm.ScoreValidator;
import org.opensourcepingpong.organization.*;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.web.bind.annotation.*;

@RestController @RequestMapping("/api/v1") public class MatchController {private final JdbcTemplate jdbc;private final AuthorizationService auth;private final ScheduleService schedules;public MatchController(JdbcTemplate j,AuthorizationService a,ScheduleService s){jdbc=j;auth=a;schedules=s;}@GetMapping("/matches/{id}") ApiResponse<?> get(@PathVariable UUID id){var r=jdbc.queryForList("select * from matches where id=?",id);if(r.isEmpty())throw missing();return ApiResponse.ok(r.getFirst());}@PostMapping("/admin/matches/{id}/start") ApiResponse<Void> start(@AuthenticationPrincipal AuthPrincipal p,@PathVariable UUID id){auth.require(p.userId(),Permission.MATCH_SCORE_EDIT);int changed=jdbc.update("update matches set status='PLAYING',started_at=? where id=? and status='READY' and player_a_user_id is not null and player_b_user_id is not null",Timestamp.from(Instant.now()),id);if(changed!=1)throw state();return ApiResponse.ok(null);}@PutMapping("/admin/matches/{id}/score") ApiResponse<Void> score(@AuthenticationPrincipal AuthPrincipal p,@PathVariable UUID id,@Valid @RequestBody ScoreRequest r){auth.require(p.userId(),Permission.MATCH_SCORE_EDIT);var rows=jdbc.queryForList("select player_a_user_id,player_b_user_id,best_of,status,version from matches where id=?",id);if(rows.isEmpty())throw missing();var m=rows.getFirst();if(((Number)m.get("version")).longValue()!=r.version())throw conflict();if(!"PLAYING".equals(m.get("status")))throw state();if(m.get("player_a_user_id")==null||m.get("player_b_user_id")==null)throw state();List<ScoreValidator.Game> games=r.games().stream().map(g->new ScoreValidator.Game(g.a(),g.b())).toList();int win;try{win=ScoreValidator.matchWinner(((Number)m.get("best_of")).intValue(),games);}catch(IllegalArgumentException e){throw new BusinessException(HttpStatus.UNPROCESSABLE_ENTITY,"MATCH_INVALID_SCORE","比分不合法");}UUID winner=(UUID)m.get(win==0?"player_a_user_id":"player_b_user_id"),loser=(UUID)m.get(win==0?"player_b_user_id":"player_a_user_id");int changed=jdbc.update("update matches set status='COMPLETED',result_type='NORMAL',winner_user_id=?,loser_user_id=?,player_a_games=?,player_b_games=?,completed_at=?,version=version+1 where id=? and version=? and status='PLAYING'",winner,loser,(int)games.stream().filter(g->ScoreValidator.winner(g)==0).count(),(int)games.stream().filter(g->ScoreValidator.winner(g)==1).count(),Timestamp.from(Instant.now()),id,r.version());if(changed!=1)throw conflict();jdbc.update("delete from match_games where match_id=?",id);for(int i=0;i<games.size();i++){var g=games.get(i);jdbc.update("insert into match_games(id,match_id,game_number,player_a_score,player_b_score,winner_user_id)values(?,?,?,?,?,?)",UUID.randomUUID(),id,i+1,g.a(),g.b(),ScoreValidator.winner(g)==0?(UUID)m.get("player_a_user_id"):(UUID)m.get("player_b_user_id"));}schedules.advance(id,winner);return ApiResponse.ok(null);}private static BusinessException missing(){return new BusinessException(HttpStatus.NOT_FOUND,"MATCH_NOT_FOUND","场次不存在");}private static BusinessException conflict(){return new BusinessException(HttpStatus.CONFLICT,"MATCH_VERSION_CONFLICT","比赛数据已被修改");}private static BusinessException state(){return new BusinessException(HttpStatus.CONFLICT,"MATCH_INVALID_STATE","场次状态不允许该操作");}public record ScoreRequest(long version,@jakarta.validation.constraints.NotEmpty List<Game> games){}public record Game(int a,int b){}}
